public sealed class DocumentParagraphView:Decorator {
 readonly HighlightBlock body=new();
 public static readonly DependencyProperty RowProperty=DependencyProperty.Register("Row",typeof(DisplayRow),typeof(DocumentParagraphView),new PropertyMetadata(null,(d,e)=>((DocumentParagraphView)d).Refresh()));
 public static readonly DependencyProperty OwnerProperty=DependencyProperty.Register("Owner",typeof(LibraryWindow),typeof(DocumentParagraphView));
 public DisplayRow? Row{get=>(DisplayRow?)GetValue(RowProperty);set=>SetValue(RowProperty,value);}public LibraryWindow? Owner{get=>(LibraryWindow?)GetValue(OwnerProperty);set=>SetValue(OwnerProperty,value);}
 public DocumentParagraphView(){Child=body;Loaded+=(_,_)=>Refresh();}
 public void Refresh(){body.Row=null;body.Row=Row;if(Row!=null&&Owner!=null)Owner.RenderReadingParagraph(this,body,Row);}
}
public sealed partial class LibraryWindow {
 ReadingOptions readingOptions=new();readonly string readingSettings=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ElansaryWordLibrary","reading-options.json");
 readonly Popup notePopup=new(){StaysOpen=true,Placement=PlacementMode.MousePoint};readonly DispatcherTimer noteCloseTimer=new(DispatcherPriority.Background){Interval=TimeSpan.FromMilliseconds(350)};readonly Border notePanel=new(){Visibility=Visibility.Collapsed,BorderBrush=Brushes.SteelBlue,BorderThickness=new Thickness(1)};readonly TextBox popupNoteText=new(){IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,MaxHeight=240};readonly TextBox bottomNoteText=new(){IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,MaxHeight=180};
 DocumentSnapshot? toolsDocument;FootnoteMap? footnoteMap;int toolsVersion;bool paragraphSelection;int? rangeAnchor,rangeEnd;Button? rangeCopy,rangeToggle;FootnoteData? activeNote;
 void InitReadingTools(DockPanel host){Title="الأنصاري — تحديد الفقرات والحواشي وإعدادات القراءة — مراجعة 5";try{if(File.Exists(readingSettings))readingOptions=JsonSerializer.Deserialize<ReadingOptions>(File.ReadAllText(readingSettings))??new();}catch(Exception e){errors.Add(e.Message);}readingOptions.Normalize();
  rangeToggle=LocalButton(viewerBar,"تحديد فقرات",()=>{paragraphSelection=!paragraphSelection;rangeToggle!.Background=paragraphSelection?Brushes.LightBlue:SystemColors.ControlBrush;if(!paragraphSelection)ClearParagraphRange();return Task.CompletedTask;});rangeCopy=LocalButton(viewerBar,"نسخ المحدد",CopyParagraphRange);rangeCopy.Visibility=Visibility.Collapsed;LocalButton(viewerBar,"إلغاء التحديد",()=>{ClearParagraphRange();return Task.CompletedTask;});LocalButton(viewerBar,"إعدادات العرض",()=>{ShowReadingSettings();return Task.CompletedTask;});
  var factory=new FrameworkElementFactory(typeof(DocumentParagraphView));factory.SetValue(DocumentParagraphView.OwnerProperty,this);factory.SetBinding(DocumentParagraphView.RowProperty,new Binding());viewer.ItemTemplate=new DataTemplate{VisualTree=factory};
  var popupContent=NoteBox(popupNoteText);popupContent.MouseEnter+=(_,_)=>noteCloseTimer.Stop();popupContent.MouseLeave+=(_,_)=>StartNoteClose();notePopup.PlacementTarget=viewer;notePopup.Child=new Border{Child=popupContent,Width=420,MaxWidth=480,Background=Brushes.White,BorderBrush=Brushes.SteelBlue,BorderThickness=new Thickness(1),Padding=new Thickness(5)};notePanel.Child=NoteBox(bottomNoteText);DockPanel.SetDock(notePanel,Dock.Bottom);host.Children.Insert(host.Children.Count-1,notePanel);noteCloseTimer.Tick+=(_,_)=>{noteCloseTimer.Stop();notePopup.IsOpen=false;};
  host.PreviewMouseLeftButtonUp+=(_,e)=>{var source=e.OriginalSource as DependencyObject;if(!InsideViewer(source))return;var note=FindNote(source);if(note!=null){e.Handled=true;ShowSelectedNote(note);return;}if(!paragraphSelection||displayed==null)return;var row=FindRow(source);if(row==null)return;int index=ReadingParagraphIndex(source,row);if(index<0||index>=displayed.Paragraphs.Length)return;e.Handled=true;rangeAnchor??=index;rangeEnd=index;UpdateRangeCopy();RefreshReadingViews();};
  host.PreviewKeyDown+=async(_,e)=>{if(e.Key==Key.Escape){ClearParagraphRange();notePopup.IsOpen=false;e.Handled=true;}else if(e.Key==Key.C&&(Keyboard.Modifiers&ModifierKeys.Control)!=0&&rangeAnchor!=null){e.Handled=true;await CopyParagraphRange();}};
  var descriptor=DependencyPropertyDescriptor.FromProperty(ItemsControl.ItemsSourceProperty,typeof(FastList));EventHandler changed=(_,_)=>Dispatcher.BeginInvoke(new Action(()=>{_=RefreshReadingDocument();}));descriptor?.AddValueChanged(viewer,changed);Closed+=(_,_)=>{toolsVersion++;descriptor?.RemoveValueChanged(viewer,changed);noteCloseTimer.Stop();notePopup.IsOpen=false;};ApplyReadingOptions();
 }
 DockPanel NoteBox(TextBox text){var panel=new DockPanel{Background=Brushes.White};var bar=new StackPanel{Orientation=Orientation.Horizontal};DockPanel.SetDock(bar,Dock.Top);panel.Children.Add(bar);var copy=new Button{Content="نسخ",Padding=new Thickness(4),Margin=new Thickness(2)};copy.Click+=(_,_)=>{try{Clipboard.SetText(text.Text);}catch(Exception e){status.Text=e.Message;}};bar.Children.Add(copy);var close=new Button{Content="إغلاق",Padding=new Thickness(4),Margin=new Thickness(2)};close.Click+=(_,_)=>{notePopup.IsOpen=false;notePanel.Visibility=Visibility.Collapsed;};bar.Children.Add(close);panel.Children.Add(text);return panel;}
 async Task RefreshReadingDocument(){var doc=displayed;if(doc==null||ReferenceEquals(doc,toolsDocument))return;int request=++toolsVersion;toolsDocument=doc;footnoteMap=null;ClearParagraphRange();notePopup.IsOpen=false;notePanel.Visibility=Visibility.Collapsed;try{var map=await Task.Run(()=>{var m=ReadingData.ReadNotes(doc.Path);var info=new FileInfo(doc.Path);if(info.Length!=doc.Length||info.LastWriteTimeUtc.Ticks!=doc.Ticks)throw new IOException("تغيّر الملف أثناء قراءة الحواشي");return m;});if(request!=toolsVersion||!ReferenceEquals(displayed,doc))return;footnoteMap=map;RefreshReadingViews();}catch(Exception e){if(request==toolsVersion){errors.Add(e.ToString());status.Text="تعذر تحميل الحواشي: "+e.Message;}}}
 static DependencyObject? ReadingParent(DependencyObject d)=>d is FrameworkContentElement c?c.Parent:d is Visual?VisualTreeHelper.GetParent(d):null;
 bool InsideViewer(DependencyObject? d){while(d!=null){if(ReferenceEquals(d,viewer))return true;d=ReadingParent(d);}return false;}
 static FootnoteData? FindNote(DependencyObject? d){while(d!=null){if(d is Hyperlink h&&h.DataContext is FootnoteData n)return n;d=ReadingParent(d);}return null;}
 int ReadingParagraphIndex(DependencyObject? d,DisplayRow row){if(row.Hit!=null)return row.Hit.Index;while(d!=null&&d is not ListBoxItem)d=ReadingParent(d);return d is ListBoxItem item?viewer.ItemContainerGenerator.IndexFromContainer(item):-1;}
 internal void RenderReadingParagraph(DocumentParagraphView view,HighlightBlock body,DisplayRow row){int index=ReadingParagraphIndex(view,row);body.FontSize=readingOptions.TextSize;body.FontFamily=new FontFamily(readingOptions.FontName);body.LineHeight=readingOptions.TextSize*readingOptions.LineFactor;body.Padding=new Thickness(6,readingOptions.ParagraphGap/2,6,readingOptions.ParagraphGap/2);if(rangeAnchor is int a&&rangeEnd is int b&&index>=Math.Min(a,b)&&index<=Math.Max(a,b))body.Background=Brushes.LightSteelBlue;if(!ReferenceEquals(toolsDocument,displayed)||footnoteMap==null||!footnoteMap.References.TryGetValue(index,out var refs))return;foreach(var group in refs.GroupBy(r=>r.Offset).OrderByDescending(g=>g.Key)){var span=new Span();foreach(var reference in group){var note=reference.Note;var link=new Hyperlink(new Run(note.Label){BaselineAlignment=BaselineAlignment.Superscript,FontSize=readingOptions.TextSize*0.75}){DataContext=note,Foreground=Brushes.DarkBlue,Cursor=Cursors.Hand,ToolTip="عرض الحاشية — ترقيم العرض بحسب ترتيب الإشارات"};link.MouseEnter+=(_,_)=>OpenNotePopup(note);link.MouseLeave+=(_,_)=>StartNoteClose();span.Inlines.Add(link);}int at=0;bool inserted=false;foreach(var run in body.Inlines.OfType<Run>().ToArray()){int length=run.Text.Length;if(group.Key<=at+length){int cut=Math.Clamp(group.Key-at,0,length);string suffix=run.Text[cut..];run.Text=run.Text[..cut];body.Inlines.InsertAfter(run,span);if(suffix.Length>0)body.Inlines.InsertAfter(span,new Run(suffix){Background=run.Background,Foreground=run.Foreground});inserted=true;break;}at+=length;}if(!inserted)body.Inlines.Add(span);}}
 void RefreshReadingViews(){foreach(var view in ReadingViews(viewer))view.Refresh();}
 static IEnumerable<DocumentParagraphView> ReadingViews(DependencyObject root){if(root is DocumentParagraphView v){yield return v;yield break;}for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in ReadingViews(VisualTreeHelper.GetChild(root,i)))yield return child;}
 void ClearParagraphRange(){rangeAnchor=null;rangeEnd=null;UpdateRangeCopy();RefreshReadingViews();}
 void UpdateRangeCopy(){if(rangeCopy==null)return;rangeCopy.Visibility=rangeAnchor!=null?Visibility.Visible:Visibility.Collapsed;if(rangeAnchor is int a&&rangeEnd is int b)rangeCopy.Content=$"نسخ المحدد ({Math.Abs(b-a)+1})";}
 async Task CopyParagraphRange(){var doc=displayed;if(doc==null||rangeAnchor is not int a||rangeEnd is not int b)return;try{string text=await Task.Run(()=>ReadingData.CopyRange(doc.Paragraphs,a,b));Clipboard.SetText(text);status.Text=$"تم نسخ {Math.Abs(b-a)+1} فقرة كاملة";}catch(Exception e){status.Text=e.Message;}}
 void OpenNotePopup(FootnoteData note){activeNote=note;noteCloseTimer.Stop();popupNoteText.Text=note.Text;popupNoteText.FontSize=readingOptions.NoteSize;notePopup.IsOpen=true;}
 void StartNoteClose(){noteCloseTimer.Stop();noteCloseTimer.Start();}
 void ShowSelectedNote(FootnoteData note){activeNote=note;noteCloseTimer.Stop();if(!readingOptions.BottomNotes){OpenNotePopup(note);return;}notePopup.IsOpen=false;bottomNoteText.Text=note.Text;bottomNoteText.FontSize=readingOptions.NoteSize;notePanel.Visibility=Visibility.Visible;}
 void ApplyReadingOptions(){readingOptions.Normalize();viewer.FontSize=readingOptions.TextSize;viewer.FontFamily=new FontFamily(readingOptions.FontName);outlineList.FontSize=readingOptions.OutlineSize;popupNoteText.FontSize=bottomNoteText.FontSize=readingOptions.NoteSize;RefreshReadingViews();}
 void ShowReadingSettings(){var window=new Window{Owner=this,Title="إعدادات القراءة — لا تغيّر ملف Word",Width=420,Height=620,FlowDirection=FlowDirection.RightToLeft,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new Thickness(15)};window.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Slider Slider(string label,double value,double min,double max){var text=new TextBlock{Margin=new Thickness(3)};panel.Children.Add(text);var s=new Slider{Minimum=min,Maximum=max,Value=value,Margin=new Thickness(3)};void Update()=>text.Text=$"{label}: {s.Value:F1}";s.ValueChanged+=(_,_)=>Update();Update();panel.Children.Add(s);return s;}var size=Slider("خط المستند",readingOptions.TextSize,10,48);var note=Slider("خط الحواشي",readingOptions.NoteSize,10,40);var outline=Slider("خط المخطط",readingOptions.OutlineSize,10,32);var line=Slider("تباعد السطور",readingOptions.LineFactor,1.1,2.5);var gap=Slider("المسافة بين الفقرات",readingOptions.ParagraphGap,0,30);panel.Children.Add(new TextBlock{Text="نوع الخط"});var font=new ComboBox{ItemsSource=Fonts.SystemFontFamilies.Select(f=>f.Source).OrderBy(s=>s).ToArray(),SelectedItem=readingOptions.FontName,Margin=new Thickness(3)};panel.Children.Add(font);var bottom=new CheckBox{Content="عرض الحاشية أسفل العارض عند الضغط؛ المرور يظهر معاينة دائمًا",IsChecked=readingOptions.BottomNotes,Margin=new Thickness(3)};panel.Children.Add(bottom);LocalButton(panel,"حفظ وتطبيق",()=>{readingOptions=new ReadingOptions{TextSize=size.Value,NoteSize=note.Value,OutlineSize=outline.Value,LineFactor=line.Value,ParagraphGap=gap.Value,FontName=font.SelectedItem as string??"Segoe UI",BottomNotes=bottom.IsChecked==true};SaveReadingOptions();window.Close();return Task.CompletedTask;});LocalButton(panel,"استعادة الافتراضي",()=>{readingOptions=new();SaveReadingOptions();window.Close();return Task.CompletedTask;});window.ShowDialog();}
 void SaveReadingOptions(){ApplyReadingOptions();try{Directory.CreateDirectory(Path.GetDirectoryName(readingSettings)!);File.WriteAllText(readingSettings,JsonSerializer.Serialize(readingOptions));}catch(Exception e){errors.Add(e.Message);status.Text="تعذر حفظ إعدادات القراءة: "+e.Message;}}
